{"description": "Crawl static site links for 404s", "code": "
const base = 'http://127.0.0.1:5199';
const htmlFiles = ['404','admin','bottle','drift-log','login','me','new','river','sea','settings']
  .map((n) => `site/${n}.html`);
const jsFiles = ['session','page-404','api','page-admin','page-drift-log','recorder','dom','page-new','page-login','page-settings','page-me','page-sea','page-bottle','top-nav','page','fit','page-river']
  .map((n) => `site/app/${n}.js`);
const urls = new Set();
for (const f of [...htmlFiles, ...jsFiles]) {
  const r = await tools.read({ file_path: `D:\\Develop\\projects\\music\\${f}` });
  const text = r.lines.map((l) => l.text).join('\n');
  for (const m of text.matchAll(/(?:src|href)=["']([^"']+)["']/g)) {
    const v = m[1];
    if (/^(https?:|mailto:|#|data:)/.test(v)) continue;
    urls.add(v.startsWith('/') ? v : `/${f.replace(/^site\//, '').replace(/\/[^/]*$/, '')}/${v}`.replace('/./', '/'));
  }
  for (const m of text.matchAll(/from\s+["']([^"']+)["']/g)) {
    const v = m[1];
    const dir = f.replace(/\/[^/]*$/, '');
    urls.add(v.startsWith('.') ? `/${dir.slice(5)}/${v.replace(/^\.\//, '')}` : v);
  }
  for (const m of text.matchAll(/["'](\/api\/[^"']*)["']/g)) urls.add(m[1].split('?')[0]);
}
const bad = [];
let ok = 0;
for (const u of [...urls].sort()) {
  try {
    const res = await fetch(base + u, { redirect: 'manual' });
    if (res.status !== 200) bad.push(`${res.status} ${u}`);
    else ok++;
  } catch (e) { bad.push(`ERR ${u} ${e.message}`); }
}
return { total: urls.size, ok, bad };
"}

